import{_ as t,o as i,c as s,ae as a}from"./chunks/framework.vXWZTEWX.js";const h=JSON.parse('{"title":"🧪 Testing Policy & Quality Assurance - TenderCheck AI","description":"","frontmatter":{},"headers":[],"relativePath":"standards/testing_policy.md","filePath":"standards/testing_policy.md"}'),o={name:"standards/testing_policy.md"};function r(n,e,c,l,d,u){return i(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="🧪-testing-policy-quality-assurance-tendercheck-ai" tabindex="-1">🧪 Testing Policy &amp; Quality Assurance - TenderCheck AI <a class="header-anchor" href="#🧪-testing-policy-quality-assurance-tendercheck-ai" aria-label="Permalink to &quot;🧪 Testing Policy &amp; Quality Assurance - TenderCheck AI&quot;">​</a></h1><h2 id="_1-core-objectives" tabindex="-1">1. Core Objectives <a class="header-anchor" href="#_1-core-objectives" aria-label="Permalink to &quot;1. Core Objectives&quot;">​</a></h2><p>[cite_start]The primary goal of the testing strategy is to ensure system reliability, auditability, and compliance with the Master&#39;s Thesis quality standards[cite: 16, 53].</p><h2 id="_2-quality-gates-mandatory" tabindex="-1">2. Quality Gates (MANDATORY) <a class="header-anchor" href="#_2-quality-gates-mandatory" aria-label="Permalink to &quot;2. Quality Gates (MANDATORY)&quot;">​</a></h2><ul><li>[cite_start]<strong>Minimum Global Coverage</strong>: A minimum of <strong>80% code coverage</strong> is required for the overall project[cite: 198, 200, 657].</li><li>[cite_start]<strong>Core Logic Coverage</strong>: Critical functions within the <code>Domain</code> layer must aim for <strong>100% coverage</strong>[cite: 199].</li><li>[cite_start]<strong>Pre-push Enforcement</strong>: Using <strong>Husky</strong>, git pushes will be blocked if tests fail or if the coverage threshold is not met[cite: 202, 657].</li></ul><h2 id="_3-testing-levels" tabindex="-1">3. Testing Levels <a class="header-anchor" href="#_3-testing-levels" aria-label="Permalink to &quot;3. Testing Levels&quot;">​</a></h2><ul><li>[cite_start]<strong>Unit Testing (Vitest)</strong>: Focus on isolated logic in the <code>Domain</code> and <code>Application</code> layers (e.g., validation rules, state transitions)[cite: 196, 646].</li><li>[cite_start]<strong>Integration Testing</strong>: Validate the communication between the <code>Application</code> layer and mocked <code>Infrastructure</code> services[cite: 646].</li><li>[cite_start]<strong>E2E Testing (Playwright)</strong>: Test the full user journey, from PDF upload to report visualization, ensuring UI/UX consistency[cite: 205, 648].</li></ul><h2 id="_4-ai-infrastructure-mocking" tabindex="-1">4. AI &amp; Infrastructure Mocking <a class="header-anchor" href="#_4-ai-infrastructure-mocking" aria-label="Permalink to &quot;4. AI &amp; Infrastructure Mocking&quot;">​</a></h2><ul><li>[cite_start]<strong>LLM Mocking</strong>: API calls to OpenAI/Anthropic must be mocked to ensure deterministic tests and avoid unnecessary costs[cite: 205].</li><li>[cite_start]<strong>PDF Parser Mocking</strong>: Use mock file streams to test how the system handles various text extraction results (valid, empty, or corrupted)[cite: 205].</li></ul><h2 id="_5-methodology-ai-assisted-tdd" tabindex="-1">5. Methodology: AI-Assisted TDD <a class="header-anchor" href="#_5-methodology-ai-assisted-tdd" aria-label="Permalink to &quot;5. Methodology: AI-Assisted TDD&quot;">​</a></h2><ol><li><strong>Test-First</strong>: Define test cases based on the <code>SRS.md</code> before writing the implementation.</li><li><strong>AI-Generated Cases</strong>: Use the IDE&#39;s AI to suggest edge cases (e.g., missing mandatory documents, ambiguous legal phrasing).</li><li>[cite_start]<strong>Refactor for Testability</strong>: Use <strong>Dependency Injection</strong> to ensure the <code>Domain</code> logic remains testable without real external dependencies[cite: 1219].</li></ol><h2 id="_6-audit-ethics-testing" tabindex="-1">6. Audit &amp; Ethics Testing <a class="header-anchor" href="#_6-audit-ethics-testing" aria-label="Permalink to &quot;6. Audit &amp; Ethics Testing&quot;">​</a></h2><ul><li>[cite_start]<strong>Traceability Validation</strong>: Tests must verify that every <code>ValidationResult</code> includes an <code>explanation</code> and a <code>decisionSource</code>[cite: 808, 1400].</li><li>[cite_start]<strong>Error Handling</strong>: Explicitly test for &quot;Ambiguous&quot; states to ensure the system correctly flags cases for human review[cite: 829, 1184].</li></ul>',13)])])}const m=t(o,[["render",r]]);export{h as __pageData,m as default};
